using System;using System.Collections.Generic;using System.Linq;using System.Web.Script.Serialization;
class MeterPushProbe{static void Main(){var clock=System.Diagnostics.Stopwatch.StartNew();var times=new List<long>();long last=0;while(clock.ElapsedMilliseconds<8000){FluentAbletonMeter.Poll();var snapshot=(Dictionary<string,object>)FluentAbletonMeter.Snapshot();foreach(var v in snapshot.Values){var json=new JavaScriptSerializer().Serialize(v);var d=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(json);long stamp=Convert.ToInt64(d["timestamp"]);if(stamp!=last){times.Add(stamp);last=stamp;}}System.Threading.Thread.Sleep(10);}FluentAbletonMeter.Idle();var gaps=new List<long>();for(int i=1;i<times.Count;i++)gaps.Add(times[i]-times[i-1]);gaps.Sort();Console.WriteLine("samples="+times.Count+" medianGapMs="+(gaps.Count>0?gaps[gaps.Count/2]:-1));if(times.Count<20)Environment.ExitCode=1;}}
